import ast
import logging
import platform
import re
import subprocess
from ipaddress import ip_address
from time import sleep, time

from taf.internal.portforwarding.ssh_connection import SshConnection

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class LinuxConfigs(object):
    received_packets_pattern = r"(\d+) received"
    ping_command = 'ping -{protocol} -c 1 -w {s}'
    shell = True


class WindowsConfig(object):
    received_packets_pattern = r"Received = (\d+)"
    ping_command = 'ping -{protocol} -n 1 -w {ms}'
    shell = False


def _get_ip_protocol_version(ip):
    return str(ip_address(ip).version)


LOCAL_HOST_CONFIGS = WindowsConfig() if platform.system() == 'Windows' else LinuxConfigs()
REMOTE_HOST_CONFIGS = LinuxConfigs()


class PingExecutor:

    @staticmethod
    def _execute_ping_command_from_remote_host(ip_addr, remote_host_ip, remote_host_username, remote_host_password,
                                               timeout):
        ip_protocol_version = _get_ip_protocol_version(ip_addr)
        connection_object = SshConnection(remote_host_username, remote_host_password, remote_host_ip)
        connection_object._setup()
        ping_output = connection_object.execute(
            "{} {} || true".format(REMOTE_HOST_CONFIGS.ping_command.format(s=timeout, ms=timeout * 1000, protocol=ip_protocol_version),
                                   ip_addr))
        connection_object._teardown()
        return ping_output

    @staticmethod
    def _run_single_ping_process(ip_addr, timeout=2, remote_host_ip=None, remote_host_username=None,
                                 remote_host_password=None):

        ip_protocol_version = _get_ip_protocol_version(ip_addr)
        if not remote_host_ip:
            command = "{} {}".format(
                LOCAL_HOST_CONFIGS.ping_command.format(s=timeout, ms=timeout * 1000, protocol=ip_protocol_version),
                ip_addr
            )
            process = subprocess.Popen(command, shell=LOCAL_HOST_CONFIGS.shell, stdout=subprocess.PIPE)
            command_output, error = process.communicate()
            command_output = command_output.decode()
        else:
            process = PingExecutor._execute_ping_command_from_remote_host(ip_addr, remote_host_ip, remote_host_username,
                                                                          remote_host_password, timeout)
            command_output = process.decode()
        return command_output

    @staticmethod
    def _collect_ping_statuses(ip_addresses, timeout=2, remote_host_ip=None, remote_host_username=None,
                               remote_host_password=None):
        """
        This method should run ping and almost instantaneously return the dictionary of ping
        statuses. True - ping success, False - fail
        :param ip_addresses: IPs to ping
        :param remote_host_ip: IP to be provided if ping should be proceeded from a Linux based remote host
        :param remote_host_username: username of remote host
        :param remote_host_password: password of remote host
        :return: dict like:
         { <IP1>: True,
           <IP2>: False}
        """
        ping_statuses = {}
        for ip_addr in ip_addresses:
            ping_statuses[ip_addr] = PingExecutor.ip_is_pingable(ip_addr, timeout, remote_host_ip,
                                                                 remote_host_username=remote_host_username,
                                                                 remote_host_password=remote_host_password)
        return ping_statuses

    @staticmethod
    def _verify_ping_statuses_and_update_counters(ping_successful_counts, ping_statuses,
                                                  expected_ping_status):
        """
        Function ads 1 to each IP dict key if ping status is as expected.
        If not, the counter is set to 0. Additionally, an info will be logged,
        if ping was in a good status before (counter > 0), but now fell back to bad status."""
        for ip_addr in ping_statuses:
            if expected_ping_status == ping_statuses[ip_addr]:
                ping_successful_counts[ip_addr] += 1
            elif ping_successful_counts[ip_addr] > 0:
                msg_to_log = "{} {} {} time{}, but it {} pinging again.".format(
                    ip_addr,
                    'pinged' if expected_ping_status else 'did not ping',
                    str(ping_successful_counts[ip_addr]),
                    's' if ping_successful_counts[ip_addr] > 1 else '',
                    'stopped' if expected_ping_status else 'started')
                logger.info(msg_to_log)
                ping_successful_counts[ip_addr] = 0

    @staticmethod
    def ip_is_pingable(ip_address, timeout=2, remote_host_ip=None, remote_host_username=None,
                       remote_host_password=None):
        """Check if IP address is pingable

        :param: ip_address: IP address to ping
        :param: timeout: timeout for the ping command
        :param remote_host_ip: IP to be provided if ping should be proceeded from a Linux based remote host
        :param remote_host_username: username of remote host
        :param remote_host_password: password of remote host
        :return: True - ping success, False - fail
        """
        output = PingExecutor._run_single_ping_process(ip_address, timeout, remote_host_ip=remote_host_ip,
                                                       remote_host_username=remote_host_username,
                                                       remote_host_password=remote_host_password)
        received_counter = re.search(LOCAL_HOST_CONFIGS.received_packets_pattern, output).groups()[0]

        all_responding_ip_addresses = re.findall(
            r"from (.*): .* time[=|<]\d", output)

        if (0 < int(received_counter) == len(all_responding_ip_addresses)
                and len(set(all_responding_ip_addresses)) == 1):
            return True
        return False

    @staticmethod
    def wait_until_multiping_status(ip_addresses, status=True, timeout=1,
                                    retry_interval=3, required_ping_count=1, remote_host_ip=None,
                                    remote_host_username=None,
                                    remote_host_password=None):
        """
        Method waits until IPs ping statuses are as expected
        :param ip_addresses: IPs to ping
        :param status: True to wait until ips are pingable, False to wait for no ping
        :param timeout: how long should method wait for IP to have expected ping status
        :param retry_interval: check ping every {retry_interval} seconds
        :param required_ping_count: required amount of pings (in a row) with expected status
        :param remote_host_ip: IP to be provided if ping should be proceeded from a Linux based remote host
        :param remote_host_username: username of remote host
        :param remote_host_password: password of remote host
        """
        ping_successful_counts = {ip: 0 for ip in ip_addresses}
        logger.debug("IP addresses: {}".format(ip_addresses))
        logger.debug("Should be pingable: {}".format(status))
        logger.debug("Timeout for expected status: {} seconds".format(int(timeout)))
        status_str = 'pingable' if status else 'not pingable.'
        start = time()
        time_before_next_ping = 1
        while not all(success_count >= required_ping_count
                      for success_count in ping_successful_counts.values()):
            sleep(max(0.0, time_before_next_ping))
            start_iter = time()
            ping_statuses = PingExecutor._collect_ping_statuses(ip_addresses, remote_host_ip=remote_host_ip,
                                                                remote_host_username=remote_host_username,
                                                                remote_host_password=remote_host_password)
            stop_iter = time()
            PingExecutor._verify_ping_statuses_and_update_counters(ping_successful_counts,
                                                                   ping_statuses,
                                                                   status)
            time_before_next_ping = int(retry_interval) - abs(stop_iter - start_iter)
            time_elapsed = stop_iter - start
            if time_elapsed > int(timeout):
                failed_ips = [ip for ip in ip_addresses if ping_successful_counts[ip] == 0]
                if failed_ips:
                    status_str = 'not' if status else 'still'
                    raise OSError("Ping timed out.\nThe following IP(s) are "
                                  "{} pingable:\n {}".format(status_str, failed_ips))
        logger.info(
            "Success, IP addresses list: {} is {} after {:.2f} seconds.".format(ip_addresses,
                                                                                status_str,
                                                                                time_elapsed))


class Operations:

    @staticmethod
    def check_non_critical_ips(ip_addresses, non_critical_ips, **kwargs):
        non_critical_ips_status = {'pingable non_critical_ips': non_critical_ips, 'not pingable non_critical_ips': []}
        try:
            PingExecutor.wait_until_multiping_status(non_critical_ips, **kwargs)
        except OSError as err:
            list_of_unpingable_ips = ast.literal_eval(str(err)[str(err).index('['):str(err).index(']') + 1])
            list_of_pingable_ips = [ip for ip in non_critical_ips if ip not in list_of_unpingable_ips]
            non_critical_ips_status = {'pingable non_critical_ips': list_of_pingable_ips,
                                       'not pingable non_critical_ips': list_of_unpingable_ips}
            logger.warning(err.args[0])
            logger.info("Trying to at least ping {}".format(ip_addresses))
            kwargs["timeout"] = 0

        if not kwargs["status"]:
            non_critical_ips_status['pingable non_critical_ips'], non_critical_ips_status[
                'not pingable non_critical_ips'] = \
                non_critical_ips_status['not pingable non_critical_ips'], non_critical_ips_status[
                    'pingable non_critical_ips']

        return non_critical_ips_status

    @staticmethod
    def wait_for_ping(ip_addresses, non_critical_ips=None, remote_host_ip=None, remote_host_username=None,
                      remote_host_password=None, **kwargs):
        kwargs = Operations._adjust_kwargs(kwargs)

        if non_critical_ips:
            non_critical_ips_status = Operations.check_non_critical_ips(ip_addresses, non_critical_ips, **kwargs)
        else:
            non_critical_ips_status = None

        PingExecutor.wait_until_multiping_status(ip_addresses, remote_host_ip=remote_host_ip,
                                                 remote_host_username=remote_host_username,
                                                 remote_host_password=remote_host_password, **kwargs)
        return non_critical_ips_status

    @staticmethod
    def wait_for_no_ping(ip_addresses, non_critical_ips=None, remote_host_ip=None, remote_host_username=None,
                         remote_host_password=None, **kwargs):
        kwargs["status"] = False
        non_critical_ips_status = Operations.wait_for_ping(ip_addresses, non_critical_ips=non_critical_ips,
                                                           remote_host_ip=remote_host_ip,
                                                           remote_host_username=remote_host_username,
                                                           remote_host_password=remote_host_password,
                                                           **kwargs)
        return non_critical_ips_status

    @staticmethod
    def ip_is_pingable(ip_address, timeout=2, remote_host_ip=None, remote_host_username=None,
                       remote_host_password=None):
        """
        Check if IP address is not pingable
        :param ip_address: IP address to ping
        :param timeout: timeout to set int the ping command
        :param remote_host_ip: IP to be provided if ping should be proceeded from a Linux based remote host
        :param remote_host_username: username of remote host
        :param remote_host_password: password of remote host
        :return: True - ping fail, False - success
        """
        return PingExecutor.ip_is_pingable(ip_address, timeout, remote_host_ip=remote_host_ip,
                                           remote_host_username=remote_host_username,
                                           remote_host_password=remote_host_password)

    @staticmethod
    def ip_is_unpingable(ip_address, timeout=2, remote_host_ip=None, remote_host_username=None,
                         remote_host_password=None):
        """
        Check if IP address is not pingable
        :param ip_address: IP address to ping
        :param timeout: timeout to set int the ping command
        :param remote_host_ip: IP to be provided if ping should be proceeded from a Linux based remote host
        :param remote_host_username: username of remote host
        :param remote_host_password: password of remote host
        :return: True - ping fail, False - success
        """
        return not PingExecutor.ip_is_pingable(ip_address, timeout, remote_host_ip=remote_host_ip,
                                               remote_host_username=remote_host_username,
                                               remote_host_password=remote_host_password)

    @staticmethod
    def _adjust_kwargs(kwargs):
        """
        Convert wait_for_ping kwargs to wait_until_multiping_status kwargs
        """
        if "status" not in kwargs:
            kwargs["status"] = True
        if "successful_ping_count" in kwargs:
            kwargs["required_ping_count"] = int(kwargs["successful_ping_count"])
        elif "unsuccessful_ping_count" in kwargs:
            kwargs["required_ping_count"] = int(kwargs["unsuccessful_ping_count"])
        kwargs.pop("successful_ping_count", "")
        kwargs.pop("unsuccessful_ping_count", "")
        return kwargs
